62	func usage() {
63		fmt.Println(`usage: govflow <command> [flags]
64	
65	legacy commands:
66	  demo                         run the built-in voting demo
67	  version                      print the version
68	
69	local treasury commands:
70	  init       --state FILE --balance N
71	             create a new state file with the initial treasury balance
72	  register   --state FILE --id ID --timelock N --action A [--action A ...]
73	             register a passed proposal (idempotent; conflicting content errors)
74	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
75	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
76	             --timelock N [--action A ...]
77	             create a voting proposal with roster, weights, delegations and a
78	             voting window (idempotent on identical content; conflict otherwise)
79	  vote       --state FILE --id ID --voter M --choice for|against --now N
80	             cast one ballot as a final representative (repeat same choice is
81	             idempotent; changing choice errors)
82	  tally      --state FILE --id ID --now N
83	             tally a proposal at/after its deadline; repeat calls return the
84	             first result
85	  execute    --state FILE --id ID --now N
86	             execute a passed proposal whose timelock has elapsed
87	             (works for both registered and voted proposals)
88	  balances   --state FILE [--account ACCT]
89	             show treasury and recipient account balances
90	  proposal   --state FILE --id ID
91	             show one registered proposal
92	  proposals  --state FILE
93	             list all registered proposals by id
94	  receipt    --state FILE --id ID
95	             show the execution receipt of one proposal
96	  receipts   --state FILE
