215		}
216	}
217	
218	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
219	type memberList []govflow.VoteMember
220	
221	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
222	func (m *memberList) Set(v string) error {
223		id, weight, err := splitMember(v)
224		if err != nil {
225			return err
226		}
227		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
228		return nil
229	}
230	
231	func splitMember(raw string) (string, int64, error) {
232		idx := strings.LastIndex(raw, ":")
233		if idx <= 0 || idx == len(raw)-1 {
234			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
235		}
236		id := raw[:idx]
237		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
238		if err != nil {
239			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
240		}
241		return id, weight, nil
242	}
243	
244	// delegationList 收集重复的 --delegate FROM:TO 参数原文，保持提交顺序。
245	// 成员编号本身可含冒号（如 team:alice），FROM 与 TO 两端都可能含冒号，
246	// 因此不能在解析单个参数时切分：必须等完整成员名单齐备后，
247	// 由 resolveDelegations 结合名单确定唯一的切分点。
248	type delegationList []string
249	
250	func (d *delegationList) String() string { return fmt.Sprint([]string(*d)) }
251	func (d *delegationList) Set(v string) error {
252		*d = append(*d, v)
253		return nil
254	}
255	
256	// delegationUsageError 是 --delegate 的参数错误（格式错误或切分有歧义），
257	// 以退出码 2 结束；格式正确但无法匹配名单的错误不属于此类，按域错误退出码 1 处理。
258	type delegationUsageError struct{ reason string }
259	
260	func (e *delegationUsageError) Error() string { return e.reason }
261	
262	// resolveDelegations 结合本次提交的完整成员名单理解每条 FROM:TO 委托原文。
263	// 成员编号保持原文并区分大小写；编号可含冒号，所以一条委托原文在每个冒号
264	// 位置都有一种候选切分。恰好一种切分让两端都是名单成员时按该对成员创建委托；
265	// 多种切分都成立时该委托有歧义，整项拒绝（参数错误），不能默认选择任意一对，
266	// 也不拿自委托/重复/循环等业务规则替用户消除歧义；格式正确但没有任何切分
267	// 能匹配名单时按域错误拒绝并指出无法匹配的参数。成员与委托参数在命令行上的
268	// 排列先后不影响结果：解析前名单已收集完毕。
269	func resolveDelegations(members []govflow.VoteMember, raws []string) ([]govflow.Delegation, error) {
270		roster := make(map[string]bool, len(members))
271		for _, m := range members {
272			roster[m.ID] = true
273		}
274		out := make([]govflow.Delegation, 0, len(raws))
275		for _, raw := range raws {
276			from, to, ok := strings.Cut(raw, ":")
277			if !ok || from == "" || to == "" {
278				return nil, &delegationUsageError{fmt.Sprintf("malformed delegation %q, expected FROM:TO", raw)}
279			}
280			var matches []govflow.Delegation
281			for i := 0; i < len(raw); i++ {
282				if raw[i] != ':' {
283					continue
284				}
285				if f, t := raw[:i], raw[i+1:]; roster[f] && roster[t] {
286					matches = append(matches, govflow.Delegation{From: f, To: t})
287				}
288			}
289			switch len(matches) {
290			case 0:
291				return nil, fmt.Errorf("delegation %q does not match any pair of members on the roster", raw)
292			case 1:
293				out = append(out, matches[0])
294			default:
295				pairs := make([]string, len(matches))
296				for i, m := range matches {
297					pairs[i] = fmt.Sprintf("%q delegating to %q", m.From, m.To)
298				}
299				return nil, &delegationUsageError{fmt.Sprintf("ambiguous delegation %q: could mean %s",
300					raw, strings.Join(pairs, " or "))}
301			}
302		}
303		return out, nil
304	}
305	
306	func runCreateVote(args []string) {
307		cf := newCmdFlags("create-vote")
308		id := cf.fs.String("id", "", "proposal id (non-empty)")
309		var members memberList
310		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
311		var delegationRaws delegationList
312		cf.fs.Var(&delegationRaws, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality; either side may itself contain colons and is matched against the full member roster)")
313		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
314		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
315		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
316		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
317		var actions actionList
318		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
319		cf.parse(args)
320		if *id == "" {
321			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
322			os.Exit(2)
323		}
324		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
325		start := parseIntFlag(cf.fs, "start", *startRaw)
326		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
327		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
328		if len(members) == 0 {
329			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
330			os.Exit(2)
331		}
332		// 委托切分依赖完整成员名单，必须在打开状态文件之前完成：
333		// 格式错误与歧义是参数错误（退出码 2），无法匹配名单是域错误（退出码 1），
334		// 两种失败都不触碰已有状态文件。
335		delegations, derr := resolveDelegations([]govflow.VoteMember(members), []string(delegationRaws))
336		if derr != nil {
337			var usageErr *delegationUsageError
338			if errors.As(derr, &usageErr) {
339				fmt.Fprintf(os.Stderr, "usage error: %v\n", derr)
340				os.Exit(2)
341			}
342			fail(derr)
343		}
344	
345		store, err := govflow.Open(cf.state)
346		if err != nil {
347			fail(err)
348		}
349		defer store.Close()
350		in := &govflow.CreateVoteInput{
351			ID:          *id,
352			Members:     []govflow.VoteMember(members),
353			Delegations: delegations,
354			Quorum:      quorum,
355			StartAt:     start,
356			Deadline:    deadline,
357			TimelockEnd: timelock,
358			Actions:     []string(actions),
359		}
360		view, existed, err := store.CreateVoteProposal(in)
361		if err != nil {
362			fail(err)
363		}
364		if cf.asJSON {
365			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
366			return
367		}
368		if existed {
369			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
370		} else {
371			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
372				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
373		}
374	}
375	
376	func runVote(args []string) {
377		cf := newCmdFlags("vote")
378		id := cf.fs.String("id", "", "proposal id to vote on")
379		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
380		choice := cf.fs.String("choice", "", "vote choice: for or against")
381		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
382		cf.parse(args)
383		if *id == "" || *voter == "" {
384			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
385			os.Exit(2)
386		}
387		var support bool
388		switch *choice {
389		case "for":
390			support = true
391		case "against":
392			support = false
393		default:
394			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
395			os.Exit(2)
396		}
397		now := parseIntFlag(cf.fs, "now", *nowRaw)
398	
399		store, err := govflow.Open(cf.state)
400		if err != nil {
401			fail(err)
402		}
403		defer store.Close()
404		ballot, err := store.CastVote(*id, *voter, support, now)
405		if err != nil {
406			fail(err)
407		}
408		if cf.asJSON {
409			emitJSON(ballot)
