112				t.Fatalf("register %d failed", i)
113			}
114		}
115	
116		var wg sync.WaitGroup
117		successes := make(chan int, n)
118		failures := make(chan string, n)
119		start := make(chan struct{})
120		for i := 0; i < n; i++ {
121			wg.Add(1)
122			go func(i int) {
123				defer wg.Done()
124				<-start
125				_, se, code := runCLI(t, binary, state, "execute", "--id", "gip-"+itoa(i), "--now", "0")
126				if code == 0 {
127					successes <- 1
128				} else {
129					failures <- se
130				}
131			}(i)
132		}
133		close(start)
134		wg.Wait()
135		close(successes)
136		close(failures)
137		got := 0
