555		if err := os.WriteFile(legal, []byte(legalRaw), 0o600); err != nil {
556			t.Fatal(err)
557		}
558		if so, se, code := runCLI(t, binary, legal, "proposal", "--id", "gip-legal"); code != 0 {
559			t.Fatalf("legal false/0 ballot text query exit=%d: %s", code, se)
560		} else if !strings.Contains(so, "choice=against") || !strings.Contains(so, "voted_at=0") {
561			t.Fatalf("text query should show against/0, got %q", so)
562		}
563		if so, se, code := runCLI(t, binary, legal, "proposal", "--id", "gip-legal", "--json"); code != 0 {
564			t.Fatalf("legal false/0 ballot json query exit=%d: %s", code, se)
565		} else if !strings.Contains(so, `"support": false`) || !strings.Contains(so, `"voted_at": 0`) {
566			t.Fatalf("json query should preserve false/0, got %s", so)
567		}
568	}
569	
570	// TestCLIRejectsIncompleteTally：已计票提案的计票结果缺 against_weight（该侧真实
571	// 票重恰好为 0）时，文本与 JSON 的查询、再次计票都把整份文件判为损坏：原因写入
572	// stderr（能看出提案编号、计票字段与缺失原因），以域错误退出码 1 结束，stdout
573	// 不出现成功结果，文件不被改写；请求同库内另一项正常提案也同样拒绝。
574	func TestCLIRejectsIncompleteTally(t *testing.T) {
575		binary := buildCLI(t)
576		dir := t.TempDir()
577		state := filepath.Join(dir, "treasury.json")
578		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
579			t.Fatal("init failed")
