581		if _, _, code := runCLI(t, binary, state, "create-vote", "--id", "gip-cli-tally",
582			"--member", "alice:600", "--member", "dave:400",
583			"--quorum", "600", "--start", "0", "--deadline", "10", "--timelock", "10",
584			"--action", "transfer:a:1"); code != 0 {
