586		}
587		// 同库另一项正常提案（仍在投票），用于验证损坏不被选择性忽略。
588		if _, _, code := runCLI(t, binary, state, "create-vote", "--id", "gip-other",
589			"--member", "alice:600", "--member", "dave:400",
590			"--quorum", "600", "--start", "0", "--deadline", "10", "--timelock", "10"); code != 0 {
591			t.Fatal("create-vote gip-other failed")
592		}
593		if _, _, code := runCLI(t, binary, state, "vote", "--id", "gip-cli-tally",
594			"--voter", "alice", "--choice", "for", "--now", "5"); code != 0 {
595			t.Fatal("vote failed")
596		}
597		// 计票通过：for=600、against=0、quorum=600，反对侧真实票重恰好为零。
598		if so, se, code := runCLI(t, binary, state, "tally", "--id", "gip-cli-tally", "--now", "10"); code != 0 {
599			t.Fatalf("tally exit=%d: %s", code, se)
600		} else if !strings.Contains(so, "for=600 against=0") || !strings.Contains(so, "passed") {
601			t.Fatalf("tally output = %q, want passed for=600 against=0", so)
602		}
603	
604		raw, err := os.ReadFile(state)
605		if err != nil {
606			t.Fatal(err)
607		}
608		// 删掉已保存计票结果中的 against_weight（写出的值是 0）。
609		corrupt := strings.Replace(string(raw), `"against_weight": 0,`, ``, 1)
610		if corrupt == string(raw) {
611			t.Fatal("setup: against_weight field not found")
612		}
613		if err := os.WriteFile(state, []byte(corrupt), 0o600); err != nil {
614			t.Fatal(err)
615		}
616	
617		// 文本与 JSON 采用同一判定：均为退出码 1、原因在 stderr、stdout 为空。
618		for _, args := range [][]string{
619			{"proposal", "--id", "gip-cli-tally"},
620			{"proposal", "--id", "gip-cli-tally", "--json"},
621			{"proposal", "--id", "gip-other"},
622			{"proposals"},
623			{"proposals", "--json"},
624			{"tally", "--id", "gip-cli-tally", "--now", "10"},
625			{"tally", "--id", "gip-cli-tally", "--now", "10", "--json"},
626			{"balances", "--json"},
