650	// TestCLIRejectsIncompleteReceiptOrderIndex：第一份凭据删掉 order、或第一项动作
651	// 删掉 index 时，即使资金变动与动作原文完全一致，所有读取命令也把整份状态判为
652	// 损坏：原因写入 stderr（含提案编号、字段与缺失原因；index 还含动作位置），以
653	// 域错误退出码 1 结束，stdout 不出现任何提案的部分查询结果，文件不被改写。
654	func TestCLIRejectsIncompleteReceiptOrderIndex(t *testing.T) {
655		binary := buildCLI(t)
656		dir := t.TempDir()
657		state := filepath.Join(dir, "treasury.json")
658		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
659			t.Fatal("init failed")
660		}
661		// 同一收款账户连续两项动作：缺损修复不得合并或重排记录。
662		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
663			"--timelock", "0",
664			"--action", "transfer:acct:100", "--action", "transfer:acct:50"); code != 0 {
665			t.Fatal("register failed")
666		}
667		if so, _, code := runCLI(t, binary, state, "execute", "--id", "gip-1", "--now", "0", "--json"); code != 0 ||
668			!strings.Contains(so, `"order": 0`) || !strings.Contains(so, `"index": 0`) ||
669			!strings.Contains(so, `"index": 1`) {
670			t.Fatalf("first execute should emit full order/index, code=%d so=%s", code, so)
671		}
672		// 正常查询保持不变：文本与 JSON 都输出明确保存的序号。
673		if so, _, code := runCLI(t, binary, state, "receipts"); code != 0 ||
674			!strings.Contains(so, "order=0") || !strings.Contains(so, "action 0:") ||
675			!strings.Contains(so, "action 1:") {
676			t.Fatalf("text receipts query changed: %s", so)
677		}
678	
679		raw, err := os.ReadFile(state)
680		if err != nil {
681			t.Fatal(err)
682		}
683		cases := []struct {
684			name    string
685			edit    func(string) string
686			wantMsg []string
687		}{
688			{
689				name:    "order-missing",
690				edit:    func(s string) string { return strings.Replace(s, `"order": 0,`, ``, 1) },
691				wantMsg: []string{"corrupt", "gip-1", `receipt 0`, `"order"`, "missing"},
692			},
693			{
694				name:    "index-missing",
695				edit:    func(s string) string { return strings.Replace(s, `"index": 0,`, ``, 1) },
696				wantMsg: []string{"corrupt", "gip-1", "action 0", `"index"`, "missing"},
697			},
698		}
699		for _, tc := range cases {
700			t.Run(tc.name, func(t *testing.T) {
701				corrupt := tc.edit(string(raw))
702				if corrupt == string(raw) {
703					t.Fatalf("setup: target field not found")
704				}
705				bad := filepath.Join(dir, tc.name+".json")
706				if err := os.WriteFile(bad, []byte(corrupt), 0o600); err != nil {
707					t.Fatal(err)
708				}
709				for _, args := range [][]string{
710					{"receipt", "--id", "gip-1"},
711					{"receipt", "--id", "gip-1", "--json"},
712					{"receipts"},
713					{"receipts", "--json"},
714					{"balances", "--json"},
715					{"proposals", "--json"},
716				} {
717					so, se, code := runCLI(t, binary, bad, args...)
718					if code != 1 {
719						t.Fatalf("%v exit=%d want 1, stdout=%q stderr=%q", args, code, so, se)
720					}
721					if so != "" {
722						t.Fatalf("%v stdout must stay empty on corruption, got %q", args, so)
723					}
724					for _, want := range tc.wantMsg {
725						if !strings.Contains(se, want) {
726							t.Fatalf("%v stderr %q missing %q", args, se, want)
727						}
728					}
729				}
730				// 不整理、补齐或覆盖缺损文件。
731				if got, err := os.ReadFile(bad); err != nil || string(got) != corrupt {
732					t.Fatalf("corrupt file was modified or rewritten")
733				}
734			})
735		}
